claims = []
for i, (o, n, tag, extra) in enumerate(C, 1):
    assert o in O, ("OLD", o)
    assert n in N, ("NEW", n)
    c = {"id": f"C-{i:03d}", "old": o, "new": n, "where": "new",
         "cites": sorted(set(CITE.findall(o)))}
    nc = extra.get("newcites", sorted(set(CITE.findall(n))))
    if set(nc) != set(c["cites"]): c["newcites"] = sorted(set(nc))
    c["tag"] = tag
    if "ruling" in extra: c["ruling"] = extra["ruling"]
    claims.append(c)
# The ruled R16 sentence is an addition; add it as a claim too, tied to the R6 span.
for a in ADDED: assert a in N, ("ADDED", a)
json.dump({"claims": claims, "added": ADDED},
          open("ch11/units/H/inventory.json", "w"), indent=1, ensure_ascii=False)
print(len(claims), "claims")
